  /* compress input to output. Return bytes read, -1 on error */
  func gz_compress(_ inx : FileDescriptor, _ out : FileDescriptor, _ gsizep : inout off_t, _ origname : String, _ mtime : UInt32) -> off_t {
    z_stream z;
    char *outbufp, *inbufp;
    off_t in_tot = 0, out_tot = 0;
    ssize_t in_size;
    int i, error;
    uLong crc;

    outbufp = malloc(BUFLEN);
    inbufp = malloc(BUFLEN);
    if (outbufp == NULL || inbufp == NULL) {
      maybe_err("malloc failed");
      goto out;
    }

    memset(&z, 0, sizeof z);
    z.zalloc = Z_NULL;
    z.zfree = Z_NULL;
    z.opaque = 0;

    if (nflag != 0) {
      mtime = 0;
      origname = "";
    }

    i = snprintf(outbufp, BUFLEN, "%c%c%c%c%c%c%c%c%c%c%s",
                 GZIP_MAGIC0, GZIP_MAGIC1, Z_DEFLATED,
                 *origname ? ORIG_NAME : 0,
                 mtime & 0xff,
                 (mtime >> 8) & 0xff,
                 (mtime >> 16) & 0xff,
                 (mtime >> 24) & 0xff,
                 numflag == 1 ? 4 : numflag == 9 ? 2 : 0,
                 OS_CODE, origname);
    if (i >= BUFLEN) {
      /* this need PATH_MAX > BUFLEN ... */
      maybe_err("snprintf");
    }
    if (*origname) {
      i++;
    }

    z.next_out = (unsigned char *)outbufp + i;
    z.avail_out = BUFLEN - i;

    error = deflateInit2(&z, numflag, Z_DEFLATED,
                         (-MAX_WBITS), 8, Z_DEFAULT_STRATEGY);
    if (error != Z_OK) {
      maybe_warnx("deflateInit2 failed");
      in_tot = -1;
      goto out;
    }

    crc = crc32(0L, Z_NULL, 0);
    for (;;) {
      if (z.avail_out == 0) {
        if (write_retry(out, outbufp, BUFLEN) != BUFLEN) {
          maybe_warn("write");
          out_tot = -1;
          goto out;
        }

        out_tot += BUFLEN;
        z.next_out = (unsigned char *)outbufp;
        z.avail_out = BUFLEN;
      }

      if (z.avail_in == 0) {
        in_size = read(in, inbufp, BUFLEN);
        if (in_size < 0) {
          maybe_warn("read");
          in_tot = -1;
          goto out;
        }
        if (in_size == 0) {
          break;
        }
        infile_newdata(in_size);

        crc = crc32(crc, (const Bytef *)inbufp, (unsigned)in_size);
        in_tot += in_size;
        z.next_in = (unsigned char *)inbufp;
        z.avail_in = in_size;
      }

      error = deflate(&z, Z_NO_FLUSH);
      if (error != Z_OK && error != Z_STREAM_END) {
        maybe_warnx("deflate failed");
        in_tot = -1;
        goto out;
      }
    }

    /* clean up */
    for (;;) {
      size_t len;
      ssize_t w;

      error = deflate(&z, Z_FINISH);
      if (error != Z_OK && error != Z_STREAM_END) {
        maybe_warnx("deflate failed");
        in_tot = -1;
        goto out;
      }

      len = (char *)z.next_out - outbufp;

      w = write_retry(out, outbufp, len);
      if (w == -1 || (size_t)w != len) {
        maybe_warn("write");
        out_tot = -1;
        goto out;
      }
      out_tot += len;
      z.next_out = (unsigned char *)outbufp;
      z.avail_out = BUFLEN;

      if (error == Z_STREAM_END) {
        break;
      }
    }

    if (deflateEnd(&z) != Z_OK) {
      maybe_warnx("deflateEnd failed");
      in_tot = -1;
      goto out;
    }

    i = snprintf(outbufp, BUFLEN, "%c%c%c%c%c%c%c%c",
                 (int)crc & 0xff,
                 (int)(crc >> 8) & 0xff,
                 (int)(crc >> 16) & 0xff,
                 (int)(crc >> 24) & 0xff,
                 (int)in_tot & 0xff,
                 (int)(in_tot >> 8) & 0xff,
                 (int)(in_tot >> 16) & 0xff,
                 (int)(in_tot >> 24) & 0xff);
    if (i != 8) {
      maybe_err("snprintf");
    }
    if (write_retry(out, outbufp, i) != i) {
      maybe_warn("write");
      in_tot = -1;
    } else {
      out_tot += i;
    }

  out:
    if (inbufp != NULL) {
      free(inbufp);
    }
    if (outbufp != NULL) {
      free(outbufp);
    }
    if (gsizep) {
      *gsizep = out_tot;
    }
    return in_tot;
  }

