//    char *outbufp, *inbufp;
//    uint32_t out_sub_tot = 0;
    enum GZstate{
      case MAGIC0
      case MAGIC1
      case METHOD
      case FLAGS
      case SKIPPING
      case EXTRA
      case EXTRA2
      case EXTRA3
      case ORIGNAME
      case COMMENT
