    var crc = 0
    var wr : ssize_t = 0
    var needmore = 0

//    #define ADVANCE()       { z.next_in++; z.avail_in--; }

    if ((outbufp = malloc(BUFLEN)) == NULL) {
      maybe_err("malloc failed");
      goto out2;
    }
    if ((inbufp = malloc(BUFLEN)) == NULL) {
      maybe_err("malloc failed");
      goto out1;
    }

    var z = z_stream()
//    z.avail_in = prelen
    z.next_in = 0 // use next_in as an index into pre (as opposed to a pointer starting at pre)
    z.avail_out = BUFLEN
    z.next_out = outbufp
    z.zalloc = nil
    z.zfree = nil
    z.opaque = 0

    var in_tot = prelen
    var out_tot = 0

  outer:
    while true {
      check_siginfo();
      if (z.avail_in == 0 || needmore) && done_reading == 0 {
        ssize_t in_size;

        if (z.avail_in > 0) {
          memmove(inbufp, z.next_in, z.avail_in);
        }
        z.next_in = (unsigned char *)inbufp;
        in_size = read(in, z.next_in + z.avail_in,
                       BUFLEN - z.avail_in);

        if (in_size == -1) {
          maybe_warn("failed to read stdin");
          out_tot = -1
          break outer
        } else if (in_size == 0) {
          done_reading = 1;
        }
        infile_newdata(in_size);

        z.avail_in += in_size;
        needmore = 0;

        in_tot += in_size;
      }
      if (z.avail_in == 0) {
        if (done_reading && state != GZSTATE_MAGIC0) {
          maybe_warnx("%s: unexpected end of file",
                      filename);
          out_tot = -1
          break outer
        }
        break outer;
      }
      switch state {
        case .MAGIC0:
          if pre[z.next_in] != GZIP_MAGIC0 {
            if (in_tot > 0) {
              maybe_warnx("\(filename): trailing garbage ignored")
              exit_value = 2
              break outer
            }
            maybe_warnx("input not gziped (MAGIC0)")
            out_tot = -1
            break outer
          }
          z.next_in += 1
          state += 1
          out_sub_tot = 0;
          crc = crc32(0, Z_NULL, 0);

        case .MAGIC1:
          if pre[z.next_in] != GZIP_MAGIC1 && pre[z.next_in] != GZIP_OMAGIC1 {
            maybe_warnx("input not gziped (MAGIC1)");
            out_tot = -1
            break outer
          }
          z.next_in += 1
          state += 1

        case .METHOD:
          if pre[z.next_in] != Z_DEFLATED {
            maybe_warnx("unknown compression method");
            out_tot = -1
            break outer
          }
          z.next_in += 1
          state += 1

        case .FLAGS:
          flags = pre[z.next_in]
          z.next_in += 1
          skip_count = 6;
          state += 1

        case .SKIPPING:
          if (skip_count > 0) {
            skip_count--;
            z.next_in += 1
          } else {
            state += 1
          }

        case .EXTRA:
          if ((flags & EXTRA_FIELD) == 0) {
            state = GZSTATE_ORIGNAME;
            break;
          }
          skip_count = pre[z.next_in]
          z.next_in += 1
          state += 1

        case .EXTRA2:
          skip_count |= (pre[z.next_in] << 8)
          z.next_in += 1
          state += 1

        case .EXTRA3:
          if (skip_count > 0) {
            skip_count--;
            z.next_in += 1
          } else {
            state += 1
          }

        case .ORIGNAME:
          if ((flags & ORIG_NAME) == 0) {
            state += 1
            break;
          }
          if pre[z.next_in] == 0 {
            state += 1
          }
          z.next_in += 1

        case .COMMENT:
          if ((flags & COMMENT) == 0) {
            state += 1
            break;
          }
          if pre[z.next_in] == 0 {
            state += 1
          }
          z.next_in += 1

        case .HEAD_CRC1:
          if (flags & HEAD_CRC) {
            skip_count = 2;
          }
          else {
            skip_count = 0;
          }
          state++;

        case .HEAD_CRC2:
          if (skip_count > 0) {
            skip_count--;
            z.next_in += 1
          } else {
            state += 1
          }

        case .INIT:
          if (inflateInit2(&z, -MAX_WBITS) != Z_OK) {
            maybe_warnx("failed to inflateInit");
            out_tot = -1
            break outer
