          state += 1

        case .READ:
          error = inflate(&z, Z_FINISH);
          switch (error) {
              /* Z_BUF_ERROR goes with Z_FINISH... */
            case Z_BUF_ERROR:
              if (z.avail_out > 0 && !done_reading) {
                continue;
              }

            case Z_STREAM_END:
            case Z_OK:
              break;

            case Z_NEED_DICT:
              maybe_warnx("Z_NEED_DICT error");
              out_tot = -1
              break outer
            case Z_DATA_ERROR:
              maybe_warnx("data stream error");
              out_tot = -1
              break outer
            case Z_STREAM_ERROR:
              maybe_warnx("internal stream error");
              out_tot = -1
              break outer
            case Z_MEM_ERROR:
              maybe_warnx("memory allocation error");
              out_tot = -1
              break outer

